        answer: "<div style='background-color: #f5f7fa; padding: 12px; border-left: 4px solid #2196f3; border-radius: 5px; font-size: 15px; color: #333;'><h4 style='color: #0d47a1; margin-top: 0;'>ઉકેલ:</h4>કવયિત્રીનું નામ <b>ગંગાસતી</b> છે અને આ કાવ્યનો સાહિત્ય પ્રકાર <b>ભજન (પદ)</b> છે.<br><br><div style='background-color: #fff3e0; padding: 10px; margin-top: 15px; border-radius: 5px; border-left: 4px solid #ff9800; color: #e65100; font-weight: bold;'>🚀 નિતેશ સરની શોર્ટકટ ટ્રીક: ગંગા નદી એકદમ પવિત્ર હોય છે, અને સાધુ પણ ચારિત્ર્યથી પવિત્ર (શીલવંત) હોય છે. આ રીતે 'શીલવંત સાધુ' અને 'ગંગાસતી' ની જોડી યાદ રાખી લો!</div></div>"
