        question: "<div style='color: #1a237e; font-size: 16px; font-weight: bold;'>સાચા સાધુના મનમાં શત્રુ અને મિત્ર પ્રત્યે કેવો ભાવ હોય છે?</div>",
        answer: "<div style='background-color: #f5f7fa; padding: 12px; border-left: 4px solid #2196f3; border-radius: 5px; font-size: 15px; color: #333;'><h4 style='color: #0d47a1; margin-top: 0;'>ઉકેલ:</h4>સાચા સાધુના મનમાં <b>કોઈ શત્રુ કે મિત્ર હોતો નથી</b>. તે સર્વ પ્રત્યે <b>સમદૃષ્ટિ</b> (સમાન ભાવ) રાખે છે.<br><br><div style='background-color: #fff3e0; padding: 10px; margin-top: 15px; border-radius: 5px; border-left: 4px solid #ff9800; color: #e65100; font-weight: bold;'>🚀 નિતેશ સરની શોર્ટકટ ટ્રીક: સાધુ એટલે ઝીરો ભેદભાવ. જે વખાણ કરે એ પણ વહાલો અને ગાળ આપે એ પણ વહાલો! એમના માટે શત્રુ કે મિત્ર એવું કોઈ ફોલ્ડર મગજમાં હોતું જ નથી.</div></div>"
