        answer: "<div style='background-color: #f5f7fa; padding: 12px; border-left: 4px solid #2196f3; border-radius: 5px; font-size: 15px; color: #333;'><h4 style='color: #0d47a1; margin-top: 0;'>ઉકેલ:</h4><b>અર્થ:</b> સમજણ શક્તિનો ઉદય થવો / બ્રહ્માવસ્થા (ચોથી અવસ્થા) પ્રાપ્ત થવી.<br><b>વાક્ય:</b> સાચા સદ્ગુરુ મળી જાય ત્યારે મનુષ્યનો તૂરીયાનો તાર જાગી ઊઠે છે.<br><br><div style='background-color: #fff3e0; padding: 10px; margin-top: 15px; border-radius: 5px; border-left: 4px solid #ff9800; color: #e65100; font-weight: bold;'>🚀 નિતેશ સરની શોર્ટકટ ટ્રીક: મનુષ્યની ત્રણ અવસ્થા હોય (જાગ્રત, સ્વપ્ન, સુષુપ્તિ). પણ ભક્ત જ્યારે ઈશ્વર સાથે સીધો કનેક્ટ થઈ જાય (Wifi ચાલુ થઈ જાય) ત્યારે તેને ચોથી 'તૂરીયા' અવસ્થા કહેવાય. એટલે કે બ્રહ્મજ્ઞાન થઈ જવું!</div></div>"
