        question: "<div style='color: #1a237e; font-size: 16px; font-weight: bold;'>'માણસ પોતાના શરીર સાથે નિર્દયતાપૂર્વક વર્તે છે' - આમાં નિર્દયતા એટલે શું? <br>(A) દયા વગરનું (B) પ્રેમ (C) કસરત (D) આરામ</div>",
